        return CustomerCreate(
            email = model.email,
            fullName = listOf(model.firstName, model.lastName).joinToString(" "),
            status = pair(mapOf("ACTIVE" to "active", "BLOCKED" to "blocked"), when (model.status) { CustomerState.ACTIVE -> "ACTIVE"; CustomerState.BLOCKED -> "BLOCKED" }, null),
            createdAt = LocalDateTime.ofInstant(Instant.ofEpochSecond(model.signedUp), ZoneOffset.UTC),
            balanceCents = Math.round((model.balance.toDouble() * 100.0)).toInt(),
            // TODO: nickname: the matching waits for review (nickname)
            // TODO: country: no field of the model gives it
        )
    }

    /** A row of the customers table as a CustomerForm. */
    fun customerReadToCustomerForm(row: CustomerRead): CustomerForm {
        return CustomerForm(
            email = row.email,
            firstName = TODO("firstName: Mapper's relation only goes the other way (firstName, lastName)"),
            lastName = TODO("lastName: Mapper's relation only goes the other way (firstName, lastName)"),
            status = when (pair(mapOf("active" to "ACTIVE", "blocked" to "BLOCKED"), row.status, null)) { "ACTIVE" -> CustomerState.ACTIVE; "BLOCKED" -> CustomerState.BLOCKED; else -> throw IllegalArgumentException("No CustomerState for this value") },
            signedUp = row.createdAt.toInstant(ZoneOffset.UTC).epochSecond,
            balance = (row.balanceCents.toDouble() / 100.0).toBigDecimal(),
            nickname = TODO("nickname: the matching waits for review (nickname)"),
            legacyCode = null,
            notes = null,
        )
    }

    /** The value an enum pair gives, or the fallback; a value without a pair is an error. */
    private fun pair(pairs: Map<String, String>, value: String, fallback: String?): String =
