package app.repositories

import app.common.Page
import app.entities.Customer
import app.entities.CustomerTable
import app.errors.ConflictException
import org.jetbrains.exposed.v1.core.ResultRow
import org.jetbrains.exposed.v1.core.SortOrder
import org.jetbrains.exposed.v1.core.eq
import org.jetbrains.exposed.v1.exceptions.ExposedSQLException
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.deleteWhere
import org.jetbrains.exposed.v1.jdbc.insert
import org.jetbrains.exposed.v1.jdbc.selectAll
import org.jetbrains.exposed.v1.jdbc.transactions.transaction as exposedTransaction
import org.jetbrains.exposed.v1.jdbc.update

/** Keeps customers rows in the database, through Exposed. Every call joins the transaction already open, or is committed at once. */
class SqlCustomerRepository(private val db: Database) : CustomerRepository {
    override fun findById(id: Int): Customer? {
        return exposedTransaction(db) {
            CustomerTable.selectAll().where { CustomerTable.id eq id }.map { toEntity(it) }.singleOrNull()
        }
    }

    override fun list(offset: Int, limit: Int): Page<Customer> {
        return exposedTransaction(db) {
            val query = CustomerTable.selectAll()
            val total = query.count()
            val items = query.orderBy(CustomerTable.id to SortOrder.ASC).limit(limit).offset(offset.toLong()).map { toEntity(it) }
            Page(items, total, offset, limit)
        }
    }

    override fun findByEmail(email: String): Customer? {
        return exposedTransaction(db) {
            CustomerTable.selectAll().where { CustomerTable.email eq email }.map { toEntity(it) }.singleOrNull()
        }
    }

    override fun insert(entity: Customer): Customer {
        return write {
            val statement = CustomerTable.insert { row ->
                entity.email?.let { row[CustomerTable.email] = it }
                entity.fullName?.let { row[CustomerTable.fullName] = it }
                entity.status?.let { row[CustomerTable.status] = it }
                entity.createdAt?.let { row[CustomerTable.createdAt] = it }
                entity.balanceCents?.let { row[CustomerTable.balanceCents] = it }
                entity.nickname?.let { row[CustomerTable.nickname] = it }
                entity.country?.let { row[CustomerTable.country] = it }
            }
            entity.id = statement[CustomerTable.id]
            fill(entity, CustomerTable.selectAll().where { CustomerTable.id eq entity.id!! }.single())
            entity
        }
    }

    override fun update(entity: Customer): Customer {
        return write {
            CustomerTable.update({ CustomerTable.id eq entity.id!! }) { row ->
                entity.email?.let { row[CustomerTable.email] = it }
                entity.fullName?.let { row[CustomerTable.fullName] = it }
                entity.status?.let { row[CustomerTable.status] = it }
                entity.createdAt?.let { row[CustomerTable.createdAt] = it }
                entity.balanceCents?.let { row[CustomerTable.balanceCents] = it }
                row[CustomerTable.nickname] = entity.nickname
                entity.country?.let { row[CustomerTable.country] = it }
            }
            entity
        }
    }

    override fun delete(entity: Customer): Unit {
        write {
            CustomerTable.deleteWhere { CustomerTable.id eq entity.id!! }
        }
    }

    private fun toEntity(row: ResultRow): Customer = Customer().also { fill(it, row) }

    private fun fill(entity: Customer, row: ResultRow) {
        entity.id = row[CustomerTable.id]
        entity.email = row[CustomerTable.email]
        entity.fullName = row[CustomerTable.fullName]
        entity.status = row[CustomerTable.status]
        entity.createdAt = row[CustomerTable.createdAt]
        entity.balanceCents = row[CustomerTable.balanceCents]
        entity.nickname = row[CustomerTable.nickname]
        entity.country = row[CustomerTable.country]
    }

    /** Runs a write in a transaction; a database refusal (a unique value, a row still pointed to) becomes a ConflictException. */
    private fun <T> write(work: () -> T): T =
        try {
            exposedTransaction(db) { work() }
        } catch (error: ExposedSQLException) {
            // SQLSTATE class 23: the change breaks a constraint (SQLite says so in its message)
            if (!error.sqlState.startsWith("23") && error.cause?.message?.contains("SQLITE_CONSTRAINT") != true) throw error
            throw ConflictException("Customer", "the database refused the change: ${error.cause?.message}")
        }
}

