package app.services

import app.UnitOfWork
import app.common.Page
import app.dtos.CustomerCreate
import app.dtos.CustomerRead
import app.dtos.CustomerUpdate
import app.entities.Customer
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException
import java.time.LocalDateTime

/** Operations on customers. Each write runs in its own transaction. */
class CustomerService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Customer after checking it. */
    fun createCustomer(data: CustomerCreate): CustomerRead {
        val values = mapOf(
            "email" to data.email,
            "fullName" to data.fullName,
            "status" to data.status,
            "createdAt" to data.createdAt,
            "balanceCents" to data.balanceCents,
            "nickname" to data.nickname,
            "country" to data.country,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = Customer()
            applyValues(entity, values)
            read(uow.customers.insert(entity))
        }
    }

    /** The Customer with this key; NotFoundException when there is none. */
    fun getCustomer(id: Int): CustomerRead = read(find(unitOfWork, id))

    /** A page of customers, by primary key. */
    fun listCustomers(offset: Int, limit: Int): Page<CustomerRead> = unitOfWork.customers.list(offset, limit).map { read(it) }

    /** Changes the given values of a Customer. */
    fun updateCustomer(id: Int, changes: CustomerUpdate): CustomerRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            checkValues(uow, values, current)
            applyValues(current, values)
            read(uow.customers.update(current))
        }
    }

    /** Deletes a Customer. */
    fun deleteCustomer(id: Int) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            uow.customers.delete(current)
        }
    }

    /** The Customer with this email, or null. */
    fun findCustomerByEmail(email: String): CustomerRead? = unitOfWork.customers.findByEmail(email)?.let { read(it) }

    /** Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Customer?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["email"]
            if (value == null) {
                if (creating || "email" in values) errors += FieldError("email", "is required")
            } else {
                if (value is String && value.length > 120) errors += FieldError("email", "is longer than 120 characters")
            }
        }
        run {
            val value = values["fullName"]
            if (value == null) {
                if (creating || "fullName" in values) errors += FieldError("full_name", "is required")
            } else {
                if (value is String && value.length > 120) errors += FieldError("full_name", "is longer than 120 characters")
            }
        }
        run {
            val value = values["status"]
            if (value == null) {
                if (creating || "status" in values) errors += FieldError("status", "is required")
            } else {
                if (value is String && value.length > 10) errors += FieldError("status", "is longer than 10 characters")
                if (value.toString() !in listOf("active", "blocked")) errors += FieldError("status", "must be one of: active, blocked")
            }
        }
        run {
            val value = values["createdAt"]
            if (value == null) {
                if (creating || "createdAt" in values) errors += FieldError("created_at", "is required")
            }
        }
        run {
            val value = values["balanceCents"]
            if (value == null) {
                if (creating || "balanceCents" in values) errors += FieldError("balance_cents", "is required")
            }
        }
        run {
            val value = values["nickname"]
            if (value != null) {
                if (value is String && value.length > 40) errors += FieldError("nickname", "is longer than 40 characters")
            }
        }
        run {
            val value = values["country"]
            if (value == null) {
                if (creating || "country" in values) errors += FieldError("country", "is required")
            } else {
                if (value is String && value.length > 2) errors += FieldError("country", "is longer than 2 characters")
            }
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Customer", errors)
    }

    /** Values that must be unique are not taken by another row. */
    private fun checkUnique(uow: UnitOfWork, values: Map<String, Any?>, current: Customer?) {
        run {
            val email = if ("email" in values) values["email"] as String? else current?.email
            if (email != null) {
                val other = uow.customers.findByEmail(email)
                if (other != null && (current == null || other.id != current.id))
                    throw ConflictException("Customer", "email is already taken", listOf("email"))
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Customer?) {
        validate(uow, values, current)
        checkUnique(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Customer, values: Map<String, Any?>) {
        if ("email" in values) entity.email = values["email"] as String?
        if ("fullName" in values) entity.fullName = values["fullName"] as String?
        if ("status" in values) entity.status = values["status"] as String?
        if ("createdAt" in values) entity.createdAt = values["createdAt"] as LocalDateTime?
        if ("balanceCents" in values) entity.balanceCents = values["balanceCents"] as Int?
        if ("nickname" in values) entity.nickname = values["nickname"] as String?
        if ("country" in values) entity.country = values["country"] as String?
    }

    /** The Customer with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Int): Customer =
        uow.customers.findById(id) ?: throw NotFoundException("Customer", id)

    /** The Customer as services return it. */
    private fun read(entity: Customer): CustomerRead =
        CustomerRead(
            id = entity.id!!,
            email = entity.email!!,
            fullName = entity.fullName!!,
            status = entity.status!!,
            createdAt = entity.createdAt!!,
            balanceCents = entity.balanceCents!!,
            nickname = entity.nickname,
            country = entity.country!!,
        )

    /** The values an update gives, by field. */
    private fun given(changes: CustomerUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.email.isPresent) values["email"] = changes.email.value
        if (changes.fullName.isPresent) values["fullName"] = changes.fullName.value
        if (changes.status.isPresent) values["status"] = changes.status.value
        if (changes.createdAt.isPresent) values["createdAt"] = changes.createdAt.value
        if (changes.balanceCents.isPresent) values["balanceCents"] = changes.balanceCents.value
        if (changes.nickname.isPresent) values["nickname"] = changes.nickname.value
        if (changes.country.isPresent) values["country"] = changes.country.value
        return values
    }
}

